<div class="d-flex justify-content-between align-items-start mb-4"><div><h1 class="page-title">Sales</h1><p class="page-subtitle">Manage client sales, order status, and revenue visibility.</p></div></div><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Sale</th><th>Client</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($sales as $sale): ?><tr><td>#<?= (int)$sale['id'] ?></td><td><?= htmlspecialchars($sale['client_name']??'Walk-in') ?></td><td><?= htmlspecialchars($sale['sale_date']) ?></td><td>$<?= number_format((float)$sale['total_amount'],2) ?></td><td><?= htmlspecialchars($sale['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h5>Record sale</h5><form method="post" action="?controller=sales&action=create" class="vstack gap-3"><?= $this->csrfField() ?><select class="form-select" name="client_id"><option value="">Select client</option><?php foreach($clients as $c): ?><option value="<?= (int)$c['id'] ?>"><?= htmlspecialchars($c['company_name']) ?></option><?php endforeach; ?></select><input class="form-control" type="date" name="sale_date" value="<?= date('Y-m-d') ?>"><input class="form-control" type="number" step="0.01" name="total_amount" placeholder="Total amount"><button class="btn btn-primary">Record sale</button></form></div></div></div></div>
